package main

import "fmt"

func swap(a, b *int) { // take addresses so we touch the originals
	*a, *b = *b, *a    // swap the values at those addresses
}

func main() {
	x, y := 1, 2
	swap(&x, &y)        // pass the addresses
	fmt.Println(x, y)   // 2 1
}

