package solution

func Clamp(n *int, lo, hi int) {
	if n == nil { // never dereference a nil pointer
		return
	}
	if *n < lo {
		*n = lo   // pull up to the lower bound
	} else if *n > hi {
		*n = hi   // pull down to the upper bound
	}
}

