func TestClamp(t *testing.T) {
	cases := []struct {
		in, lo, hi, want int
	}{
		{5, 0, 10, 5},
		{-3, 0, 10, 0},
		{42, 0, 10, 10},
	}
	for _, c := range cases {
		v := c.in
		Clamp(&v, c.lo, c.hi)
		if v != c.want {
			t.Errorf("Clamp(%d,%d,%d)=%d want %d", c.in, c.lo, c.hi, v, c.want)
		}
	}
	Clamp(nil, 0, 10) // must not panic
}

