type Node struct {
	Val  int
	Next *Node
}

func Reverse(head *Node) *Node {
	var prev *Node          // new list grows behind us
	cur := head
	for cur != nil {
		next := cur.Next    // remember the rest before rewiring
		cur.Next = prev     // flip this node's link backward
		prev = cur          // advance prev and cur one step
		cur = next
	}
	return prev             // prev is the old tail = new head
}
